cards.solution:
function tambahHari(teks, n) {
  const d = new Date(teks + "T00:00:00Z");
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}
console.log(tambahHari("2026-10-18", 7));
console.log(tambahHari("2026-12-30", 3));
console.log(tambahHari("2028-02-28", 1));
